场景2: SSE连接超时后自动重连（客户端30分钟超时）

此场景无法仅通过 Postman 完成，需配合前端或脚本测试。

推荐测试方式 (Node.js):
```js
const EventSource = require('eventsource');
let reconnectCount = 0;
function connect() {
  const es = new EventSource('http://localhost:8080/sse/connect/' + chatSessionId);
  es.onopen = () => console.log(`Connected (reconnect #${reconnectCount})`);
  es.onmessage = (e) => console.log('Message:', e.data);
  es.onerror = () => {
    reconnectCount++;
    console.log('Disconnected, will auto-reconnect...');
    es.close();
    setTimeout(connect, 3000);
  };
}
connect();
```

验证要点:
- 30分钟超时后连接断开
- 客户端自动重连成功
- 重连后 chatSessionId 一致
- 新消息推送正常

场景4: 并发多个SSE连接

推荐使用 k6 进行并发 SSE 压测:
```js
import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    sse_concurrent: {
      executor: 'per-vu-iterations',
      vus: 50,
      iterations: 1,
      maxDuration: '2m',
    },
  },
};

export default function () {
  // 每个 VU 先创建自己的 session
  const sessionRes = http.post('http://localhost:8080/api/chat-sessions', 
    JSON.stringify({ agentId: 'test-agent', title: `k6-session-${__VU}` }),
    { headers: { 'Content-Type': 'application/json' } });
  const sessionId = sessionRes.json('data.chatSessionId');

  // 建立 SSE 连接
  const res = http.get(`http://localhost:8080/sse/connect/${sessionId}`,
    { headers: { 'Accept': 'text/event-stream' }, timeout: '60s' });
  check(res, {
    'SSE status 200': (r) => r.status === 200,
    'Content-Type correct': (r) => r.headers['Content-Type'].includes('text/event-stream'),
  });
}
```

验证要点:
- 50个并发 SSE 连接全部成功建立
- 各连接消息路由正确，互不干扰
- 服务端线程池/连接池无泄漏

场景5: 大量消息推送压力测试

推荐使用 k6 + Grafana 进行压力测试:
```js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Trend } from 'k6/metrics';

const msgLatency = new Trend('message_latency');

export const options = {
  scenarios: {
    message_flood: {
      executor: 'constant-arrival-rate',
      rate: 100,
      timeUnit: '1s',
      duration: '30s',
      preAllocatedVUs: 50,
    },
  },
};

export default function () {
  const start = Date.now();
  const res = http.post('http://localhost:8080/api/chat-messages',
    JSON.stringify({
      sessionId: 'stress-test-session',
      role: 'user',
      content: `Stress test message ${Date.now()}`
    }),
    { headers: { 'Content-Type': 'application/json' } });
  msgLatency.add(Date.now() - start);
  check(res, { 'message sent': (r) => r.status === 200 || r.status === 201 });
}
```

SSE 接收端监控 (Node.js):
```js
const EventSource = require('eventsource');
let received = 0, outOfOrder = 0, lastTimestamp = 0;
const es = new EventSource('http://localhost:8080/sse/connect/stress-test-session');
es.onmessage = (e) => {
  received++;
  const data = JSON.parse(e.data);
  if (data.timestamp < lastTimestamp) outOfOrder++;
  lastTimestamp = data.timestamp;
  if (received % 100 === 0) console.log(`Received: ${received}, OutOfOrder: ${outOfOrder}`);
};
```

验证要点:
- 1000+ 条消息无丢失
- 消息顺序一致
- P99 延迟 < 500ms
- 服务端无内存泄漏（通过 JVM 监控 heap 使用）

